// 8-Directional Archer Sprites (Base64 embedded for instant zero-latency rendering)
window.ARCHER_8DIR_SPRITES = {
    "N": "data:image/png;base64,",
    "NE": "data:image/png;base64,",
    "E": "data:image/png;base64,",
    "SE": "data:image/png;base64,",
    "S": "data:image/png;base64,",
    "SW": "data:image/png;base64,",
    "W": "data:image/png;base64,",
    "NW": "data:image/png;base64,",
};

// Helper to calculate 8-way direction from angle in radians
window.get8WayDirection = function(dx, dy) {
    let deg = Math.atan2(dy, dx) * (180 / Math.PI);
    deg = (deg + 360) % 360;
    if (deg >= 337.5 || deg < 22.5) return "E";
    if (deg >= 22.5 && deg < 67.5) return "SE";
    if (deg >= 67.5 && deg < 112.5) return "S";
    if (deg >= 112.5 && deg < 157.5) return "SW";
    if (deg >= 157.5 && deg < 202.5) return "W";
    if (deg >= 202.5 && deg < 247.5) return "NW";
    if (deg >= 247.5 && deg < 292.5) return "N";
    if (deg >= 292.5 && deg < 337.5) return "NE";
    return "S";
};
